mapper.select:


    inner join sys_user u on u.user_name = dequipmenttree.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    dequipmenttree.del_flag = '0'
     and dequipmenttree.name like concat('%', #{name}, '%')
     and dequipmenttree.pid = #{pid}
     and dequipmenttree.type = #{type}


${params.dataScope}
